import React from "react";

const dot = (on) => ({
  display: "inline-block", width: 8, height: 8, borderRadius: "50%",
  background: on ? "#22c55e" : "#ef4444", marginRight: 6,
});

export default function StatusBar({ connected, engineOnline, alertCount }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 24,
      padding: "10px 24px", background: "#1a1d27",
      borderBottom: "1px solid #2a2d3a", fontSize: 13,
    }}>
      <span style={{ fontWeight: 600, fontSize: 15, color: "#e8e6df", letterSpacing: 0.3 }}>
        Alcohol Detector
      </span>
      <span style={{ color: "#9ca3af" }}>
        <span style={dot(connected)} />
        {connected ? "Dashboard connected" : "Disconnected"}
      </span>
      <span style={{ color: "#9ca3af" }}>
        <span style={dot(engineOnline)} />
        {engineOnline ? "Detection engine online" : "Engine offline"}
      </span>
      <span style={{ marginLeft: "auto", color: "#9ca3af" }}>
        Total alerts: <strong style={{ color: "#e8e6df" }}>{alertCount}</strong>
      </span>
    </div>
  );
}
